def database_argument(path) -> str:
    value = os.fspath(path)
    if os.name != "nt" or value == ":memory:":
        return value
    value = os.path.abspath(value)
    if value.startswith("\\\\?\\"):
        return value
    return "\\\\?\\UNC\\" + value[2:] if value.startswith("\\\\") else "\\\\?\\" + value


